import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const path=name=>fileURLToPath(new URL(name,import.meta.url));
const normalize='_M0FP210JingLan0v03stn9normalize';
const relax='_M0FP210JingLan0v03stn13relax_2einner';
const header=`const stats={normalizations:0,zero:0,negative:0,positive:0,subtractions:0,normalizeMs:0,relaxations:0,relaxMs:0};
const savedNormalize=${normalize};
${normalize}=values=>{
 stats.normalizations++;
 const origin=BigInt.asIntN(64,values[0]);
 if(origin===0n)stats.zero++;
 else if(origin<0n)stats.negative++;
 else stats.positive++;
 stats.subtractions+=values.length;
 const start=performance.now();
 try{return savedNormalize(values);}
 finally{stats.normalizeMs+=performance.now()-start;}
};
const savedRelax=${relax};
${relax}=(...args)=>{
 stats.relaxations++;
 const start=performance.now();
 try{return savedRelax(...args);}
 finally{stats.relaxMs+=performance.now()-start;}
};
process.once('exit',()=>console.error(JSON.stringify(stats)));\n`;
for(const name of ['deepbench','lookupbench']){
 const source=readFileSync(path('base-'+name+'.js'),'utf8');
 for(const fn of [normalize,relax]) assert(source.includes('function '+fn+'('));
 writeFileSync(path('base-'+name+'-probe.js'),header+source);
}
const rows=[];
for(const name of ['tight-impossible','maintenance','independent','distinct-resources','first-pair','four-resources','one-resource','max-model','max-root','zero-origin']){
 const args=name==='tight-impossible'?[path('base-deepbench-probe.js')]:[path('base-lookupbench-probe.js'),name];
 const samples=Array.from({length:3},()=>{
  const p=spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
  assert.equal(p.status,0,p.stderr);
  assert.equal(p.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(p.stderr);
 });
 rows.push({name,samples});
 console.log(name,JSON.stringify(samples[0]));
}
writeFileSync(path('base-probe.json'),JSON.stringify(rows,null,2)+'\n');

